//go:build e2e

package e2e

import (
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"

	"github.com/stretchr/testify/require"
)

// TestE2E_DebugOpenCodeHooks is a temporary debug test to investigate why
// OpenCode plugin hooks don't fire during `opencode run`.
func TestE2E_DebugOpenCodeHooks(t *testing.T) {
	t.Parallel()

	if defaultAgent != AgentNameOpenCode {
		t.Skip("debug test only for opencode agent")
	}

	env := NewFeatureBranchEnv(t, "manual-commit")

	// Dump the plugin file
	pluginPath := filepath.Join(env.RepoDir, ".opencode", "plugins", "entire.ts")
	pluginData, err := os.ReadFile(pluginPath)
	if err != nil {
		t.Logf("ERROR: Plugin file not found at %s: %v", pluginPath, err)
	} else {
		t.Logf("Plugin file (%s):\n%s", pluginPath, string(pluginData))
	}

	// Check .entire/settings.json
	settingsPath := filepath.Join(env.RepoDir, ".entire", "settings.json")
	settingsData, err := os.ReadFile(settingsPath)
	if err != nil {
		t.Logf("ERROR: Settings file not found: %v", err)
	} else {
		t.Logf("Settings: %s", string(settingsData))
	}

	// Check if `entire` is in PATH
	entirePath, err := exec.LookPath("entire")
	t.Logf("entire binary in PATH: %s (err: %v)", entirePath, err)

	// Check if `opencode` is in PATH
	opencodePath, err := exec.LookPath("opencode")
	t.Logf("opencode binary in PATH: %s (err: %v)", opencodePath, err)

	// Run the agent
	t.Log("Running agent...")
	result, err := env.RunAgent(PromptCreateHelloGo.Prompt)
	require.NoError(t, err, "Agent should succeed")
	t.Logf("Agent stdout:\n%s", result.Stdout)
	t.Logf("Agent stderr:\n%s", result.Stderr)
	t.Logf("Agent exit code: %d, duration: %v", result.ExitCode, result.Duration)

	// Check if hello.go was created
	t.Logf("hello.go exists: %v", env.FileExists("hello.go"))

	// Dump .entire/logs/ if it exists
	logsDir := filepath.Join(env.RepoDir, ".entire", "logs")
	logEntries, err := os.ReadDir(logsDir)
	if err != nil {
		t.Logf("No .entire/logs/ directory: %v", err)
	} else {
		t.Logf("Found %d log files in .entire/logs/", len(logEntries))
		for _, entry := range logEntries {
			logPath := filepath.Join(logsDir, entry.Name())
			data, _ := os.ReadFile(logPath)
			// Show last 2000 chars to avoid overwhelming output
			content := string(data)
			if len(content) > 2000 {
				content = "...(truncated)..." + content[len(content)-2000:]
			}
			t.Logf("Log file %s:\n%s", entry.Name(), content)
		}
	}

	// Check .git/entire-sessions/
	sessionsDir := filepath.Join(env.RepoDir, ".git", "entire-sessions")
	sessionEntries, err := os.ReadDir(sessionsDir)
	if err != nil {
		t.Logf("No .git/entire-sessions/ directory: %v", err)
	} else {
		t.Logf("Found %d session files in .git/entire-sessions/", len(sessionEntries))
		for _, entry := range sessionEntries {
			sessionPath := filepath.Join(sessionsDir, entry.Name())
			data, _ := os.ReadFile(sessionPath)
			t.Logf("Session file %s:\n%s", entry.Name(), string(data))
		}
	}

	// Check git branches for shadow branches
	repo := env.OpenRepo()
	refs, _ := repo.References()
	t.Log("Git references:")
	refs.ForEach(func(ref interface{ Name() interface{ String() string }; Hash() interface{ String() string } }) error {
		t.Logf("  %s -> %s", ref.Name().String(), ref.Hash().String())
		return nil
	})

	// List all files in .opencode/ to verify plugin was persisted
	opencodeDir := filepath.Join(env.RepoDir, ".opencode")
	t.Logf("Contents of %s:", opencodeDir)
	filepath.Walk(opencodeDir, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return nil
		}
		rel, _ := filepath.Rel(env.RepoDir, path)
		t.Logf("  %s (size: %d)", rel, info.Size())
		return nil
	})

	// Try running entire hooks manually to see if they work
	t.Log("Testing manual hook invocation...")
	hookCmd := exec.Command(getTestBinary(), "hooks", "opencode", "session-start")
	hookCmd.Dir = env.RepoDir
	hookCmd.Stdin = strings.NewReader(`{"session_id": "test-debug-session"}`)
	hookOutput, hookErr := hookCmd.CombinedOutput()
	t.Logf("Manual hook result: err=%v output=%s", hookErr, string(hookOutput))
}

