func NewTestEnv(t *testing.T) *TestEnv {
	t.Helper()

	var repoDir string
	if e2eRepoBaseDir != "" {
		// Create test repo inside the module root (e.g., for OpenCode which
		// rejects file writes in OS temp dirs as "external directories").
		var err error
		repoDir, err = os.MkdirTemp(e2eRepoBaseDir, t.Name()+"-*")
		if err != nil {
			t.Fatalf("failed to create test repo dir: %v", err)
		}
		t.Cleanup(func() { os.RemoveAll(repoDir) })
	} else {
		repoDir = t.TempDir()
	}

	// Resolve symlinks on macOS where /var -> /private/var
	if resolved, err := filepath.EvalSymlinks(repoDir); err == nil {
		repoDir = resolved
	}

